<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\DB;use App\Models\User;use App\Models\StatusPost;use App\Models\AppNotificationItem;use App\Services\BuddyService;
final class V1013BuddyCommunityTest extends TestCase {
 use RefreshDatabase;
 private function people():array {config(['restoration.enabled'=>true]);return [User::factory()->create(['is_synthetic'=>true,'phone'=>fake()->unique()->numerify('199########')]),User::factory()->create(['is_synthetic'=>true,'phone'=>fake()->unique()->numerify('199########')]),User::factory()->create(['is_synthetic'=>true,'phone'=>fake()->unique()->numerify('199########')])];}
 private function enabled(User $u):void {$this->actingAs($u,'sanctum')->putJson('/api/v1/buddy/preferences',['enabled'=>true,'revision'=>0])->assertOk();}
 private function draft(User $u,string $type='MEAL'):array {return $this->actingAs($u,'sanctum')->postJson('/api/v1/buddy/activities',['type'=>$type,'subject'=>'一起学习','general_city'=>'合成城市','place_kind'=>'ONLINE','budget_band'=>'LOW','start_at'=>now()->addHour()->toIso8601String(),'end_at'=>now()->addHours(2)->toIso8601String(),'idempotency_key'=>uniqid('create-')])->assertCreated()->json();}
 private function action(User $u,array $a,string $action):array {return $this->actingAs($u,'sanctum')->postJson('/api/v1/buddy/'.$a['id'].'/actions',['action'=>$action,'revision'=>$a['revision'],'idempotency_key'=>uniqid('action-')])->assertOk()->json();}
 private function open(User $a):array {$this->enabled($a);return $this->action($a,$this->draft($a),'open');}
 private function friend(User $a,User $b):void {DB::table('friendships')->insert(['user_a'=>min($a->id,$b->id),'user_b'=>max($a->id,$b->id),'state'=>'ACTIVE','revision'=>1,'created_at'=>now(),'updated_at'=>now()]);}
 private function postFixture(User $a,string $audience='FRIENDS'):StatusPost {return StatusPost::create(['author_user_id'=>$a->id,'title'=>'私有合成帖子','body'=>'PRIVATE_POST_SENTINEL','audience'=>$audience,'visibility'=>'private','is_deleted'=>false]);}
 public function test_non_romantic_token_buddy_completes_without_creating_any_other_consent():void {[$a,$b]=$this->people();$activity=$this->open($a);$this->enabled($b);$issued=$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/'.$activity['id'].'/tokens',['revision'=>$activity['revision'],'idempotency_key'=>'issue'])->assertOk()->json();$this->assertMatchesRegularExpression('/^[a-f0-9]{64}$/',$issued['token']);$r=$this->actingAs($b,'sanctum')->postJson('/api/v1/buddy/redeem',['token'=>$issued['token'],'idempotency_key'=>'redeem'])->assertOk()->json();$this->assertSame('REQUESTED',$r['state']);$this->postJson('/api/v1/buddy/redeem',['token'=>$issued['token'],'idempotency_key'=>'replay'])->assertNotFound();$r=$this->action($a,$r,'confirm');$r=$this->action($b,$r,'complete');$this->assertSame('COMPLETED',$r['state']);$this->assertDatabaseCount('buddy_slots',0);foreach(['dating_matches','matching_participations','friendships','product_connections','messaging_consents','formal_relationships','conversations'] as $t)$this->assertDatabaseCount($t,0);$this->assertDatabaseCount('buddy_audits',6);}
 public function test_friend_invite_permission_decline_blocks_same_lifecycle_reinvitation():void {[$a,$b,$c]=$this->people();$activity=$this->open($a);$this->friend($a,$b);$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/'.$activity['id'].'/invites',['recipient_id'=>$b->id,'revision'=>$activity['revision'],'idempotency_key'=>'closed'])->assertNotFound();$this->enabled($b);$activity=$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/'.$activity['id'].'/invites',['recipient_id'=>$b->id,'revision'=>$activity['revision'],'idempotency_key'=>'invite'])->assertOk()->json();$this->actingAs($c,'sanctum')->getJson('/api/v1/buddy/'.$activity['id'])->assertNotFound();$v=$this->actingAs($b,'sanctum')->getJson('/api/v1/buddy/'.$activity['id'])->assertOk()->json();$this->assertContains('request',$v['allowed_actions']);$v=$this->action($b,$v,'decline_invite');$before=AppNotificationItem::count();$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/'.$activity['id'].'/invites',['recipient_id'=>$b->id,'revision'=>$v['revision'],'idempotency_key'=>'reinvite'])->assertStatus(409);$this->assertSame($before,AppNotificationItem::count());}
 public function test_three_active_slots_expire_without_needing_a_prior_get():void {[$a]=$this->people();for($i=0;$i<3;$i++)$this->draft($a);$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/activities',['type'=>'MEAL','subject'=>'一起吃饭','place_kind'=>'ONLINE','budget_band'=>'UNSPECIFIED','start_at'=>now()->addHour()->toIso8601String(),'end_at'=>now()->addHours(2)->toIso8601String(),'idempotency_key'=>'fourth'])->assertStatus(409);$this->assertDatabaseCount('buddy_activities',3);DB::table('buddy_activities')->update(['end_at'=>now()->subMinute()]);$this->draft($a);$this->assertDatabaseCount('buddy_slots',1);$this->assertSame(3,DB::table('buddy_activities')->where('state','EXPIRED')->count());}
 public function test_contact_and_chinese_number_addresses_are_rejected_server_side():void {[$a]=$this->people();foreach([['subject'=>'到幸福路八号吃饭'],['general_city'=>'北京市幸福路八号'],['subject'=>'联系一三八一二三四五六七八'],['subject'=>'加微信一起聊']] as $bad){$d=array_merge(['type'=>'STUDY','subject'=>'一起学习','general_city'=>'合成城市','place_kind'=>'ONLINE','budget_band'=>'LOW','start_at'=>now()->addHour()->toIso8601String(),'end_at'=>now()->addHours(2)->toIso8601String(),'idempotency_key'=>uniqid()],$bad);$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/activities',$d)->assertStatus(422);}$this->assertDatabaseCount('buddy_activities',0);$this->draft($a);}
 public function test_preference_off_on_revokes_buddy_and_old_token():void {[$a,$b]=$this->people();$v=$this->open($a);$this->enabled($b);$t=$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/'.$v['id'].'/tokens',['revision'=>$v['revision'],'idempotency_key'=>'token'])->assertOk()->json();$this->actingAs($a,'sanctum')->putJson('/api/v1/buddy/preferences',['enabled'=>false,'revision'=>1])->assertOk();$this->putJson('/api/v1/buddy/preferences',['enabled'=>true,'revision'=>2])->assertOk();$this->actingAs($b,'sanctum')->postJson('/api/v1/buddy/redeem',['token'=>$t['token'],'idempotency_key'=>'bad'])->assertNotFound();$this->assertDatabaseCount('buddy_slots',0);$this->assertDatabaseCount('moderation_reports',0);}
 public function test_study_friend_buddy_can_confirm_and_cancel_without_revoking_existing_CN_MC():void {[$a,$b]=$this->people();$this->friend($a,$b);$this->enabled($a);$this->enabled($b);$v=$this->action($a,$this->draft($a,'STUDY'),'open');$v=$this->actingAs($a,'sanctum')->postJson('/api/v1/buddy/'.$v['id'].'/invites',['recipient_id'=>$b->id,'revision'=>$v['revision'],'idempotency_key'=>'friend'])->assertOk()->json();$v=$this->action($b,$v,'request');$v=$this->action($a,$v,'confirm');$counts=[DB::table('friendships')->count(),DB::table('product_connections')->count(),DB::table('messaging_consents')->count()];$this->action($b,$v,'withdraw');$this->assertSame($counts,[DB::table('friendships')->count(),DB::table('product_connections')->count(),DB::table('messaging_consents')->count()]);$this->assertDatabaseCount('buddy_slots',0);}
 public function test_current_friend_comment_like_notification_and_tombstone_use_same_audience():void {[$a,$b,$c]=$this->people();$this->friend($a,$b);$p=$this->postFixture($a);$this->actingAs($c,'sanctum')->getJson('/api/v1/status-posts/'.$p->id.'/comments')->assertNotFound();$r=$this->actingAs($b,'sanctum')->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'合成评论正文','idempotency_key'=>'c1'])->assertCreated()->json();$this->getJson('/api/v1/status-posts/'.$p->id.'/comments')->assertOk()->assertJsonPath('items.0.body','合成评论正文');$this->postJson('/api/v1/status/posts/'.$p->id.'/likes')->assertOk();$this->assertDatabaseCount('status_post_likes',1);$this->actingAs($a,'sanctum')->postJson('/api/v1/status-posts/'.$p->id.'/comments/'.$r['id'].'/report',['reason_code'=>'other'])->assertOk();$this->assertDatabaseCount('moderation_reports',1);$this->actingAs($b,'sanctum')->deleteJson('/api/v1/status-posts/'.$p->id.'/comments/'.$r['id'],['revision'=>1])->assertOk();$this->getJson('/api/v1/status-posts/'.$p->id.'/comments/'.$r['id'])->assertOk()->assertJsonPath('body',null);$n=AppNotificationItem::where('kind','status_comment')->first();$present=app(\App\Services\NotificationService::class)->presentationForUser($n,$a->id);$this->assertSame([],$present['payload']);$this->actingAs($a,'sanctum')->putJson('/api/v1/status/posts/'.$p->id.'/audience',['audience'=>'SELF'])->assertOk();$this->actingAs($b,'sanctum')->getJson('/api/v1/status/posts/'.$p->id)->assertNotFound();$this->getJson('/api/v1/status-posts/'.$p->id.'/comments')->assertNotFound();$this->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'无权评论','idempotency_key'=>'c2'])->assertNotFound();$this->assertDatabaseCount('status_post_comments',1);}
 public function test_comment_limits_idempotency_and_unsupported_fields():void {[$a,$b]=$this->people();$this->friend($a,$b);$p=$this->postFixture($a);$this->actingAs($b,'sanctum');for($i=0;$i<5;$i++)$this->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'合成评论'.$i,'idempotency_key'=>'k'.$i])->assertCreated();$this->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'合成评论0','idempotency_key'=>'k0'])->assertOk();$this->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'第六条','idempotency_key'=>'k5'])->assertStatus(429);$this->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'测试','idempotency_key'=>'forged','author_id'=>$a->id])->assertStatus(422);$this->postJson('/api/v1/status-posts/'.$p->id.'/comments',['body'=>'https://example.invalid','idempotency_key'=>'link'])->assertStatus(422);$this->assertDatabaseCount('status_post_comments',5);}
}
